
#include "motor.h"
#include "main.h"

/* TIM3 handle generated by CubeMX */
extern TIM_HandleTypeDef htim3;

/* ================= PIN CONFIGURATION ================= */

/* TB6612FNG STBY */
#define MOTOR_STBY_PORT       GPIOA
#define MOTOR_STBY_PIN        GPIO_PIN_5

/* Motor A - Left */
#define MOTOR_A_IN1_PORT      GPIOB
#define MOTOR_A_IN1_PIN       GPIO_PIN_12

#define MOTOR_A_IN2_PORT      GPIOB
#define MOTOR_A_IN2_PIN       GPIO_PIN_13

#define MOTOR_A_PWM_CHANNEL   TIM_CHANNEL_1

/* Motor B - Right */
#define MOTOR_B_IN1_PORT      GPIOB
#define MOTOR_B_IN1_PIN       GPIO_PIN_14

#define MOTOR_B_IN2_PORT      GPIOB
#define MOTOR_B_IN2_PIN       GPIO_PIN_15

#define MOTOR_B_PWM_CHANNEL   TIM_CHANNEL_2

/* PWM configuration */
#define MOTOR_PWM_MAX         3599U

/* ================= PRIVATE FUNCTIONS ================= */

static void Motor_SetDirection(
    Motor_ID_t motor,
    GPIO_PinState in1,
    GPIO_PinState in2)
{
    if (motor == MOTOR_LEFT)
    {
        HAL_GPIO_WritePin(
            MOTOR_A_IN1_PORT,
            MOTOR_A_IN1_PIN,
            in1);

        HAL_GPIO_WritePin(
            MOTOR_A_IN2_PORT,
            MOTOR_A_IN2_PIN,
            in2);
    }
    else if (motor == MOTOR_RIGHT)
    {
        HAL_GPIO_WritePin(
            MOTOR_B_IN1_PORT,
            MOTOR_B_IN1_PIN,
            in1);

        HAL_GPIO_WritePin(
            MOTOR_B_IN2_PORT,
            MOTOR_B_IN2_PIN,
            in2);
    }
}

static void Motor_SetPWM(
    Motor_ID_t motor,
    uint16_t pwm)
{
    if (motor == MOTOR_LEFT)
    {
        __HAL_TIM_SET_COMPARE(
            &htim3,
            MOTOR_A_PWM_CHANNEL,
            pwm);
    }
    else if (motor == MOTOR_RIGHT)
    {
        __HAL_TIM_SET_COMPARE(
            &htim3,
            MOTOR_B_PWM_CHANNEL,
            pwm);
    }
}

/* ================= PUBLIC FUNCTIONS ================= */

Motor_Status_t Motor_Init(void)
{
    /* Keep driver in standby during initialization */
    HAL_GPIO_WritePin(
        MOTOR_STBY_PORT,
        MOTOR_STBY_PIN,
        GPIO_PIN_RESET);

    /* Initial direction: coast */
    Motor_SetDirection(
        MOTOR_LEFT,
        GPIO_PIN_RESET,
        GPIO_PIN_RESET);

    Motor_SetDirection(
        MOTOR_RIGHT,
        GPIO_PIN_RESET,
        GPIO_PIN_RESET);

    Motor_SetPWM(MOTOR_LEFT, 0);
    Motor_SetPWM(MOTOR_RIGHT, 0);

    /* Start PWM channels */
    if (HAL_TIM_PWM_Start(
            &htim3,
            MOTOR_A_PWM_CHANNEL) != HAL_OK)
    {
        return MOTOR_ERROR;
    }

    if (HAL_TIM_PWM_Start(
            &htim3,
            MOTOR_B_PWM_CHANNEL) != HAL_OK)
    {
        HAL_TIM_PWM_Stop(
            &htim3,
            MOTOR_A_PWM_CHANNEL);

        return MOTOR_ERROR;
    }

    /* Enable TB6612FNG */
    HAL_GPIO_WritePin(
        MOTOR_STBY_PORT,
        MOTOR_STBY_PIN,
        GPIO_PIN_SET);

    return MOTOR_OK;
}

Motor_Status_t Motor_SetSpeed(
    Motor_ID_t motor,
    int16_t speed)
{
    uint16_t pwm;

    GPIO_PinState in1;
    GPIO_PinState in2;

    /* Validate motor */
    if ((motor != MOTOR_LEFT) &&
        (motor != MOTOR_RIGHT))
    {
        return MOTOR_ERROR;
    }

    /* Limit speed */
    if (speed > 100)
    {
        speed = 100;
    }
    else if (speed < -100)
    {
        speed = -100;
    }

    /* Zero speed: coast */
    if (speed == 0)
    {
        Motor_Stop(motor);
        return MOTOR_OK;
    }

    /* Calculate PWM duty */
    if (speed > 0)
    {
        in1 = GPIO_PIN_SET;
        in2 = GPIO_PIN_RESET;

        pwm = ((uint32_t)speed * MOTOR_PWM_MAX) / 100U;
    }
    else
    {
        in1 = GPIO_PIN_RESET;
        in2 = GPIO_PIN_SET;

        pwm = ((uint32_t)(-speed) * MOTOR_PWM_MAX) / 100U;
    }

    /* Avoid changing direction under active PWM */
    Motor_SetPWM(motor, 0);

    Motor_SetDirection(motor, in1, in2);

    Motor_SetPWM(motor, pwm);

    return MOTOR_OK;
}

void Motor_Stop(Motor_ID_t motor)
{
    if ((motor != MOTOR_LEFT) &&
        (motor != MOTOR_RIGHT))
    {
        return;
    }

    Motor_SetPWM(motor, 0);

    Motor_SetDirection(
        motor,
        GPIO_PIN_RESET,
        GPIO_PIN_RESET);
}

void Motor_StopAll(void)
{
    Motor_Stop(MOTOR_LEFT);
    Motor_Stop(MOTOR_RIGHT);
}

void Motor_Disable(void)
{
    Motor_StopAll();

    HAL_GPIO_WritePin(
        MOTOR_STBY_PORT,
        MOTOR_STBY_PIN,
        GPIO_PIN_RESET);
}
